package com.nanless.paperdigest.data

import com.nanless.paperdigest.cloud.*
import org.json.*
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.nio.file.Files
import java.util.UUID
import java.util.concurrent.CancellationException

class ExportProducerReceiptTest {
 private fun personal(endpoint:String="https://fixture.invalid/v1")=JSONObject().put("schema",1).put("notes",JSONObject()).put("settings",JSONObject().put("endpoint",endpoint).put("model","fixture").put("dailyRequests",5)).put("favorites",JSONArray()).put("reading",JSONArray()).put("readingState",JSONObject()).put("annotations",JSONObject()).put("sessions",JSONArray()).put("jobs",JSONArray())
 private fun temp(body:(File)->Unit){val root=Files.createTempDirectory("producer-fixture-").toRealPath().toFile();try{body(root)}finally{root.deleteRecursively()}}
 private data class Fixture(val parent:File,val op:String,val doc:String,val research:File,val directory:File,val producer:ExportProducerReceipt){val file get()=File(directory,"capture.tmp")}
 private fun fixture(parent:File):Fixture {val op=UUID.randomUUID().toString();val doc=UUID.randomUUID().toString();val research=File(parent,"Research").apply{mkdir()};File(research,"personal.json").writeText(personal().toString());File(research,".original-evidence").writeBytes(ByteArray(130001){(it%251).toByte()});val dir=File(parent,op).apply{mkdir()};return Fixture(parent,op,doc,research,dir,ExportProducerReceipt(dir,op,doc,JSONObject().put("format","backup").put("epoch","synthetic-v1")))}
 private fun cold(f:Fixture)=ExportProducerReceipt(f.directory,f.op,f.doc,JSONObject().put("format","backup").put("epoch","synthetic-v1"))
 private fun files(root:File)=root.walkTopDown().filter{it.isFile}.associate{it.relativeTo(root).path to BackupCodec.hash(it)}
 @Test fun normalCaptureProofColdRecoveryAndReservedRegistrationKeepExactOriginal()=temp{p->val f=fixture(p);val original=files(f.research);val captured=BackupCodec.capture(f.research,f.file);val complete=f.producer.recordVerifiedCapture(captured,"application/octet-stream","synthetic.paperdigest");assertEquals(captured.sha256,complete.sha256);assertTrue(cold(f).hasCompletionMaterials());val recovered=cold(f).verifiedCapture();assertEquals(captured.sha256,recovered.sha256);val writer=ExportArtifactWriter(File(p,"Exports"));val ready=writer.register(recovered.file,recovered.mime,recovered.name,f.doc);assertEquals(f.doc,ready.id);assertEquals(captured.sha256,ready.sha256);assertArrayEquals(f.file.readBytes(),ready.file.readBytes());assertEquals(original,files(f.research))}
 @Test fun validSyntacticallyCompleteTempWithoutProducerReturnNeverQualifies()=temp{p->val f=fixture(p);BackupCodec.capture(f.research,f.file);val original=f.file.readBytes();assertFalse(cold(f).hasCompletionMaterials());assertTrue(runCatching{cold(f).verifiedCapture()}.isFailure);assertArrayEquals(original,f.file.readBytes());assertFalse(File(f.directory,"producer-complete.json").exists())}
 @Test fun cancellationImmediatelyAfterNormalReturnPersistsProofBeforeCheckingCancellation()=temp{p->val f=fixture(p);val captured=BackupCodec.capture(f.research,f.file);var calls=0;assertTrue(runCatching{f.producer.recordVerifiedCapture(captured,"application/octet-stream","synthetic.paperdigest"){calls++;throw CancellationException("synthetic cancel")}}.exceptionOrNull() is CancellationException);assertEquals(1,calls);assertTrue(File(f.directory,"producer-complete.json").isFile);assertTrue(cold(f).hasCompletionMaterials());assertEquals(captured.sha256,cold(f).verifiedCapture().sha256)}
 @Test fun receiptWriteFailureRetainsInProcessNormalReturnSignalButColdCannotInventProof()=temp{p->val f=fixture(p);val captured=BackupCodec.capture(f.research,f.file);File(f.directory,"producer-complete.json").mkdir();assertTrue(runCatching{f.producer.recordVerifiedCapture(captured,"application/octet-stream","synthetic.paperdigest")}.isFailure);assertTrue(f.producer.hasCompletionMaterials());assertTrue(cold(f).hasCompletionMaterials());assertTrue(runCatching{cold(f).verifiedCapture()}.isFailure);assertEquals(captured.sha256,BackupCodec.hash(f.file))}
 @Test fun corruptedCaptureNeverRewritesProofOrRecaptures()=temp{p->val f=fixture(p);val c=BackupCodec.capture(f.research,f.file);f.producer.recordVerifiedCapture(c,"application/octet-stream","synthetic.paperdigest");val proof=File(f.directory,"producer-complete.json").readBytes();f.file.appendText("wrong");val changed=f.file.readBytes();assertTrue(runCatching{cold(f).verifiedCapture()}.isFailure);assertArrayEquals(proof,File(f.directory,"producer-complete.json").readBytes());assertArrayEquals(changed,f.file.readBytes())}
 @Test fun operationDocumentAndSourceIdentityCannotBeRetargeted()=temp{p->val f=fixture(p);val c=BackupCodec.capture(f.research,f.file);f.producer.recordVerifiedCapture(c,"application/octet-stream","synthetic.paperdigest");val before=files(f.directory);for(item in listOf(ExportProducerReceipt(f.directory,f.op,UUID.randomUUID().toString(),JSONObject().put("format","backup").put("epoch","synthetic-v1")),ExportProducerReceipt(f.directory,f.op,f.doc,JSONObject().put("format","backup").put("epoch","different"))))assertTrue(runCatching{item.verifiedCapture()}.isFailure);assertEquals(before,files(f.directory))}
 @Test fun invalidUtf8ReceiptIsNotAliasForReplacementCharacter()=temp{p->val f=fixture(p);val c=BackupCodec.capture(f.research,f.file);f.producer.recordVerifiedCapture(c,"application/octet-stream","synthetic-\uFFFD.paperdigest");val file=File(f.directory,"producer-complete.json");val raw=file.readBytes();val at=raw.indices.first{it+2<raw.size&&raw[it]==0xef.toByte()&&raw[it+1]==0xbf.toByte()&&raw[it+2]==0xbd.toByte()};val malformed=raw.copyOfRange(0,at)+byteArrayOf(0xff.toByte())+raw.copyOfRange(at+3,raw.size);file.writeBytes(malformed);assertTrue(runCatching{cold(f).verifiedCapture()}.isFailure);assertArrayEquals(malformed,file.readBytes())}
 @Test fun producerDirectoryReplacementCannotBeAdoptedAsFresh()=temp{p->val f=fixture(p);val retained=File(p,"retained");Files.move(f.directory.toPath(),retained.toPath());f.directory.mkdir();assertTrue(runCatching{f.producer.hasCompletionMaterials()}.isFailure);assertTrue(runCatching{f.producer.verifiedCapture()}.isFailure);assertTrue(f.directory.listFiles()!!.isEmpty())}
 @Test fun reservedArtifactConflictNeverOverwritesOldBinOrManifest()=temp{p->val writer=ExportArtifactWriter(File(p,"Exports"));val id=UUID.randomUUID().toString();val first=writer.bytes("exact first".toByteArray(),"text/plain","first.txt",id);val before=files(first.file.parentFile);assertTrue(runCatching{writer.bytes("second".toByteArray(),"text/plain","second.txt",id)}.isFailure);assertEquals(before,files(first.file.parentFile));assertEquals(first.sha256,writer.bytes("exact first".toByteArray(),"text/plain","first.txt",id).sha256)}
 @Test fun registeredCapacityProofFieldsArePreservedWithoutGrantingVerification()=temp{p->val dir=File(p,"Exports");val writer=ExportArtifactWriter(dir);val id=UUID.randomUUID().toString();writer.bytes("exact".toByteArray(),"text/plain","one.txt",id);val manifest=File(dir,"$id.json");val raw=JSONObject(manifest.readText()).put("savedAt","explicit synthetic proof").put("savedSHA256","a".repeat(64)).put("savedBytes",5).put("savedProofID","untrusted-value").toString().toByteArray();manifest.writeBytes(raw);writer.bytes("exact".toByteArray(),"text/plain","one.txt",id);assertArrayEquals(raw,manifest.readBytes())}
 @Test fun cancellationAfterArtifactBinPublishLeavesRecoverableExactOriginal()=temp{p->val dir=File(p,"Exports");val writer=ExportArtifactWriter(dir);val id=UUID.randomUUID().toString();val raw=ByteArray(150000){(it%253).toByte()};val failure=runCatching{writer.bytes(raw,"application/octet-stream","one.bin",id){if(File(dir,"$id.bin").let{it.isFile&&it.length()==raw.size.toLong()&&BackupCodec.hash(it)==BackupCodec.hash(raw)})throw CancellationException()}}.exceptionOrNull();assertTrue(failure is CancellationException);assertArrayEquals(raw,File(dir,"$id.bin").readBytes());assertFalse(File(dir,"$id.json").exists());assertEquals(BackupCodec.hash(raw),writer.bytes(raw,"application/octet-stream","one.bin",id).sha256)}
 @Test fun artifactDirectoryAndSymlinkReplacementDoNotAuthorizeWrite()=temp{p->val dir=File(p,"Exports");val writer=ExportArtifactWriter(dir);val retained=File(p,"retained");Files.move(dir.toPath(),retained.toPath());dir.mkdir();assertTrue(runCatching{writer.bytes("x".toByteArray(),"text/plain","x",UUID.randomUUID().toString())}.isFailure);assertTrue(dir.listFiles()!!.isEmpty());val outside=File(p,"outside").apply{writeText("original")};val id=UUID.randomUUID().toString();Files.createSymbolicLink(File(retained,"$id.bin").toPath(),outside.toPath());assertTrue(runCatching{ExportArtifactWriter(retained).bytes("x".toByteArray(),"text/plain","x",id)}.isFailure);assertEquals("original",outside.readText())}
 @Test fun mutationAfterProducerVerificationCannotPublishDifferentArtifactAsSameCompleteCapture()=temp{p->val f=fixture(p);val c=BackupCodec.capture(f.research,f.file);val complete=f.producer.recordVerifiedCapture(c,"application/octet-stream","synthetic.paperdigest");val proof=File(f.directory,"producer-complete.json").readBytes();val dir=File(p,"Exports");val writer=ExportArtifactWriter(dir);var changed=false;val failure=runCatching{writer.completed(complete.file,complete.mime,complete.name,f.doc,complete.sha256,complete.bytes){if(!changed){changed=true;f.file.appendText("changed after complete verification")}}};assertTrue(failure.isFailure);assertTrue(changed);assertFalse(File(dir,"${f.doc}.bin").exists());assertFalse(File(dir,"${f.doc}.json").exists());assertArrayEquals(proof,File(f.directory,"producer-complete.json").readBytes());assertTrue(f.file.isFile)}

}
